"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["50226"],{85342(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.ordem_invalida","status":422,"titulo":"A ordem do grupo n\xe3o pode ser negativa"},"descricao":{"codigo":"uniplus.grupo_formulario.ordem_invalida","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["A `ordem` de um grupo repet\xedvel, em `grupos`, \xe9 negativa. O grupo ocupa a posi\xe7\xe3o dele na ordem de coleta do formul\xe1rio, junto com os itens, e a posi\xe7\xe3o n\xe3o pode ser negativa. A mensagem \xe9 \\"A ordem do grupo n\xe3o pode ser negativa.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `grupos[i].ordem`, junto das demais recusas da forma do grupo. Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado.","No formul\xe1rio de inscri\xe7\xe3o, e no modelo que serve \xe0 fase de inscri\xe7\xe3o, a ordem dos grupos e dos itens que n\xe3o s\xe3o dados b\xe1sicos do candidato \xe9 deslocada para depois da se\xe7\xe3o reservada dos dados b\xe1sicos antes desta confer\xeancia, de modo que a ordem negativa de um grupo desse formul\xe1rio n\xe3o chega a ser recusada aqui. Nos formul\xe1rios de isen\xe7\xe3o de taxa e de habilita\xe7\xe3o, e nos modelos que n\xe3o servem \xe0 fase de inscri\xe7\xe3o, a ordem negativa do grupo \xe9 recusada.","Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe `ordem` com 0 ou um n\xfamero positivo, sem repetir a ordem de outro item ou grupo do mesmo formul\xe1rio."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);